As shown in the introduction, routing on normalized hidden states fails because RevIN removes the per-window statistics that distinguish input regimes. \textbf{RR-MoA} avoids this by splitting the information into two streams: the frozen TSFM produces deep embeddings $\mathbf{H}$ for the experts, while a separate lightweight gate reads the \textit{raw, pre-normalization} input $\mathbf{X}_\text{raw}$ to decide which experts to activate:
\begin{equation}
\mathbf{Y} = \sum_{j \in \mathcal{T}} \underbrace{\widetilde{w}_j}_{\text{sparse weight}} \cdot \underbrace{\text{Expert}_j(\mathbf{H}_\text{FM})}_{\text{deep embedding branch}},\quad
\mathcal{T} = \mathrm{TopK}\!\left(G_\psi(\mathbf{X}_\text{raw}),\, k\right),\;\;
\widetilde{w} = \mathrm{softmax}_{\mathcal{T}}\!\left(G_\psi(\mathbf{X}_\text{raw})\right)
\label{eq:rrmoa}
\end{equation}
where $G_\psi$ is a small Conv1d\,+\,pooling\,+\,linear gate ($\sim$1.1K params) operating directly on the raw time series, and each $\text{Expert}_k$ is a canonical adapter head. Routing is restricted to the Top-$k$ experts with the highest gate logits, so only $k$ of $K$ experts execute per sample. With $K{=}5$, $k{=}2$ we obtain $40\%$ of the dense FLOPs while retaining $63\%$ of the dense MSE gain (\S\ref{sec:topk}). The raw input preserves the temporal statistics (trend, amplitude, volatility) that RevIN strips away, enabling per-sample routing that reflects the physical characteristics of each time series window.

\begin{algorithm}[h]
\caption{RR-MoA: Raw-Routed Mixture of Adapters with Top-$k$ sparse routing}
\label{alg:rrmoa}
\begin{algorithmic}[1]
\REQUIRE Strictly frozen TSFM $f_{\theta_\text{frozen}}$, raw input $\mathbf{X}_\text{raw}\in\mathbb{R}^{B\times L}$, $K$ expert adapters, sparsity $k\leq K$
\STATE $\mathbf{H}\leftarrow f_{\theta_\text{frozen}}(\mathbf{X}_\text{raw})$ \hfill \COMMENT{Deep embeddings; \textbf{no gradients} through $\theta$}
\STATE $\mathbf{g}\leftarrow G_\psi(\mathbf{X}_\text{raw})$ \hfill \COMMENT{Raw-signal gate logits, $\mathbf{g}\in\mathbb{R}^{B\times K}$}
\STATE $\mathcal{T}\leftarrow \mathrm{TopK}(\mathbf{g},\,k)$ \hfill \COMMENT{Per-sample indices of the $k$ selected experts}
\STATE $\widetilde{\mathbf{w}}\leftarrow \mathrm{softmax}_{\mathcal{T}}(\mathbf{g})$ \hfill \COMMENT{Renormalized over selected experts only}
\STATE \textbf{for each}\ $j \in \mathcal{T}$\ \textbf{do}
\STATE \quad $\mathbf{o}_j\leftarrow \text{Expert}_j(\mathbf{H})$ \hfill \COMMENT{Only the $k$ selected experts execute}
\STATE \textbf{end for}
\STATE $\mathbf{Y}\leftarrow \sum_{j\in\mathcal{T}}\widetilde{w}_j\cdot \mathbf{o}_j$
\RETURN $\mathbf{Y}$
\end{algorithmic}
\end{algorithm}

\section{Experiments}

\subsection{Setup}

We evaluate RR-MoA on standard long-term forecasting benchmarks using five backbones, seven baselines, and up to five random seeds per configuration.

\textbf{Backbones.} Primary: MOMENT-small~\citep{goswami2024moment} ($d{=}512$, 8 blocks, internal RevIN~\citep{kim2021revin}). Cross-backbone: MOMENT-large ($d{=}1024$), Moirai~\citep{woo2024moirai} ($d{=}384$, no RevIN), Chronos~\citep{ansari2024chronos} and Timer-XL~\citep{liu2025timerxl} (no RevIN, negative controls; \S\ref{sec:cross_backbone}). Primary results use a \emph{strictly frozen} backbone; freeze-level ablations in \S\ref{sec:freeze_ablation}.

{\looseness=-1 \textbf{Datasets and tasks.} ETTh1/h2/m1/m2~\citep{zhou2021informer}, Weather (21ch), Electricity (321ch)---standard LTSF benchmarks~\citep{godahewa2021monash}. Chronological splits, channel-wise StandardScaler normalization~\citep{zhou2021informer, nie2023patchtst}. We evaluate forecasting ($H{=}96$) and imputation (20\% masked). DLinear calibration: $0.416$/$0.322$/$0.208$ on ETTh1/ETTm1/Weather (Appendix~\ref{app:dlinear}).}

\textbf{Training.} Adam optimizer, lr$=10^{-3}$, MSE loss, batch size 128, 15 epochs. Final reported numbers are 15-epoch test MSE. Multi-seed experiments use seeds $\{42, 43, 44, 45, 46\}$ ($n{=}5$) for the core table; ablations use seeds $\{42, 43, 44\}$.

{\looseness=-1 \textbf{Baselines.} Frozen: (i)~three fixed adapters (linear, attention, conv), (ii)~LoRA~\citep{hu2022lora} (108-run sweep; Appendix~\ref{app:lora_sweep}), (iii)~TRACE~\citep{li2025trace}, (iv)~independent ensemble (5 experts, no router), (v)~AdaMix~\citep{wang2022adamix} (hidden-state MoE). Unfrozen: (vi)~full fine-tuning (all 8 blocks, best of 5 heads $\times$ 2 LRs). Calibration anchor: (vii)~DLinear~\citep{zeng2023dlinear} (from scratch).}

\textbf{Reproducibility.} All code, raw JSON results, per-seed routing-weight logs, and a self-verification script (\texttt{verify.py}) that re-derives every numerical claim from raw data are included in the supplementary material and will be open-sourced upon acceptance.

\subsection{RR-MoA: Routing Collapse and Its Resolution}
\label{sec:main_results}
\label{sec:architectures}
\label{sec:freeze_ablation}

This section proceeds in four steps: we first show that RR-MoA consistently outperforms fixed adapters (Table~\ref{tab:rrmoa}), then diagnose why standard MoE routing fails (Table~\ref{tab:adamix}), demonstrate that no standard rescue mechanism recovers performance (Table~\ref{tab:rescue}), and finally compare against a comprehensive baseline suite (Table~\ref{tab:baselines}).

{\looseness=-1 \textbf{RR-MoA vs.\ fixed adapters.} Table~\ref{tab:rrmoa} compares Top-2 RR-MoA against the best fixed adapter, using the \emph{same five expert heads} in all rows. Across 6 datasets $\times$ 3 freeze levels $\times$ 3 seeds $=$ \textbf{54 configurations}, RR-MoA wins every one with tight standard deviations.}

\begin{table}[h]
\centering
\caption{\textbf{Freeze-level ablation} (test MSE, mean$\pm$std, 3 seeds, H=96). RR-MoA (Top-2, same 5 experts) vs.\ best of $\{$linear, attention, conv$\}$. RR-MoA wins \textbf{54/54} across 6 datasets (extended grid in Appendix~\ref{app:extended_rrmoa}); improvement is largest when frozen (``Frozen Paradox'').}
\label{tab:rrmoa}
\small
\begin{tabular}{@{}llccc@{}}
\toprule
Dataset & Freeze level & RR-MoA (Top-2) & Best fixed & $\Delta$\% \\
\midrule
\multirow{3}{*}{ETTh1}
 & Frozen (0/8)   & $\mathbf{0.680 \pm 0.027}$ & $1.275 \pm 0.014$ & $\mathbf{-46.7\%}$ \\
 & Last-2 (2/8)   & $\mathbf{0.723 \pm 0.064}$ & $1.030 \pm 0.139$ & $-29.8\%$ \\
 & Last-4 (4/8)   & $\mathbf{0.747 \pm 0.041}$ & $1.101 \pm 0.120$ & $-32.2\%$ \\
\midrule
\multirow{3}{*}{ETTm1}
 & Frozen (0/8)   & $\mathbf{0.564 \pm 0.059}$ & $1.116 \pm 0.036$ & $\mathbf{-49.5\%}$ \\
 & Last-2 (2/8)   & $\mathbf{0.610 \pm 0.041}$ & $0.891 \pm 0.049$ & $-31.5\%$ \\
 & Last-4 (4/8)   & $\mathbf{0.562 \pm 0.032}$ & $0.866 \pm 0.016$ & $-35.1\%$ \\
\midrule
\multirow{3}{*}{Weather}
 & Frozen (0/8)   & $\mathbf{0.276 \pm 0.017}$ & $0.538 \pm 0.026$ & $-48.7\%$ \\
 & Last-2 (2/8)   & $\mathbf{0.255 \pm 0.006}$ & $0.474 \pm 0.022$ & $-46.3\%$ \\
 & Last-4 (4/8)   & $\mathbf{0.263 \pm 0.017}$ & $0.504 \pm 0.031$ & $\mathbf{-47.8\%}$ \\
\bottomrule
\end{tabular}
\end{table}

{\looseness=-1 \textbf{The Frozen Paradox.} Frozen RR-MoA beats \emph{full fine-tuning} (all 8 blocks unfrozen, best of 5 heads $\times$ 2 LRs) by $12$--$79\%$ on every dataset (Table~\ref{tab:baselines}, Figure~\ref{fig:frozen_paradox}). The explanation is that unfreezing the backbone triggers the co-adaptation loop (Proposition~\ref{prop:frozen}): the dominant expert reshapes the shared representation, collapsing routing. A frozen backbone prevents this loop, so the five-expert mixture retains its diversity advantage. Within RR-MoA, frozen is best on 4/6 datasets; light unfreezing wins by up to $13\%$ on the other two. SR-MoA independently replicates this pattern (frozen best on 4/6 datasets; Table~\ref{tab:self_routed}). Even with careful hyperparameter tuning---learning rates $10^{-5}$ to $10^{-6}$, 100 epochs, cosine schedule with 10-epoch warmup, layerwise LR decay, weight decay sweep, gradient accumulation up to effective batch 512 (90 configurations)---full fine-tuning still loses by $51$--$71\%$ (Appendix~\ref{app:extended_ft}).}

\begin{proposition}[Gradient Co-Adaptation Drives Entropy Collapse]
\label{prop:frozen}
Consider a $2$-expert MoE with backbone $\mathbf{h}{=}A\mathbf{x}$, router $p{=}\sigma(\mathbf{w}^\top\mathbf{h})$, loss $\ell{=}p\,\ell_1{+}(1{-}p)\,\ell_2$. Under gradient descent on $(A,\mathbf{w})$: \textup{(i)} the dominant expert's loss decreases faster ($\dot{\ell}_k \propto {-}p_k\|\nabla_\mathbf{h}\ell_k\|^2$), creating self-reinforcing collapse toward $p{\in}\{0,1\}$; \textup{(ii)} freezing $A$ breaks this loop (proof in Appendix~\ref{app:proofs}).
\end{proposition}

{\looseness=-1 \textit{Remark.} Proposition~\ref{prop:frozen} covers linear $A\mathbf{x}$; Figure~\ref{fig:trajectory}b confirms it in the full 8-block Transformer within ${\sim}50$ steps. Independent ensembles are $37$--$46\%$ worse (Table~\ref{tab:baselines}): learned routing, not mere diversity, drives gains.}

\begin{table}[h]
\centering
\caption{\textbf{AdaMix routing collapse} (entropy max ${\approx}1.609$). Under unfreezing, entropy ${\to}0.000$. \colorbox{green!8}{Green}: disabling RevIN inside MOMENT recovers entropy ($0.66$--$1.32$), proving RevIN is the causal mechanism. Extended grid in Appendix~\ref{app:extended_rrmoa}.}
\label{tab:adamix}
\small
\begin{tabular}{@{}llcc@{}}
\toprule
Dataset & Freeze level & MSE (mean$\pm$std) & Routing entropy (mean$\pm$std) \\
\midrule
\multirow{4}{*}{ETTh1}
 & Frozen  & $1.105 \pm 0.026$ & $0.629 \pm 0.436$ \\
 & Last-2  & $1.153 \pm 0.000$ & $\mathbf{0.000 \pm 0.000}$ \\
 & Last-4  & $1.154 \pm 0.001$ & $\mathbf{0.000 \pm 0.000}$ \\
 & \cellcolor{green!8} Last-4 (no RevIN) & \cellcolor{green!8} $0.575 \pm 0.075$ & \cellcolor{green!8} $\mathbf{1.315 \pm 0.148}$ \\
\midrule
\multirow{4}{*}{ETTm1}
 & Frozen  & $1.008 \pm 0.012$ & $0.487 \pm 0.371$ \\
 & Last-2  & $1.061 \pm 0.088$ & $0.218 \pm 0.309$ \\
 & Last-4  & $1.123 \pm 0.000$ & $\mathbf{0.000 \pm 0.000}$ \\
 & \cellcolor{green!8} Last-4 (no RevIN) & \cellcolor{green!8} $0.426 \pm 0.072$ & \cellcolor{green!8} $\mathbf{1.103 \pm 0.376}$ \\
\midrule
\multirow{4}{*}{Weather}
 & Frozen  & $0.459 \pm 0.017$ & $0.509 \pm 0.307$ \\
 & Last-2  & $0.607 \pm 0.002$ & $\mathbf{0.000 \pm 0.000}$ \\
 & Last-4  & $0.607 \pm 0.002$ & $\mathbf{0.000 \pm 0.000}$ \\
 & \cellcolor{green!8} Last-4 (no RevIN) & \cellcolor{green!8} $0.232 \pm 0.045$ & \cellcolor{green!8} $\mathbf{0.661 \pm 0.501}$ \\
\bottomrule
\end{tabular}
\end{table}

{\looseness=-1 \textbf{Why does standard MoE routing fail?} To understand the source of RR-MoA's advantage, we examine AdaMix~\citep{wang2022adamix}, which uses the standard recipe of routing on hidden states. Table~\ref{tab:adamix} shows that AdaMix collapses to a single expert whenever backbone layers are unfrozen: entropy reaches $0.000\pm0.000$ in 7/12 unfrozen configurations and stays below $0.55$ in the remaining 5. The green rows reveal the cause: disabling RevIN inside MOMENT recovers entropy from $0.000$ to $0.66$--$1.32$, proving that normalization is the causal mechanism (BatchNorm1d and GroupNorm produce the same collapse; Appendix~\ref{app:norm_generalization}). The causal contrast is sharpest when comparing backbones directly (Figure~\ref{fig:causal_contrast}): under identical last-4 unfreezing on identical data, MOMENT entropy crashes to $0.000$ in ${\sim}40$ steps while Timer-XL (which lacks RevIN) stays at $1.60$ for all $400$ steps---opposite trajectories from the same code.}

\begin{figure}[h]
\centering
\includegraphics[width=0.92\columnwidth]{figures/adamix_trajectory.pdf}
\vspace{-4pt}
\caption{\textbf{Per-step routing / gradient trajectory} (AdaMix, ETTh1). (a)~Unfrozen+RevIN (red) collapses within ${\sim}50$ steps; frozen (blue) stays stable. Unfrozen \emph{without} RevIN (green dashed) also stays stable. (b)~Dominant expert's gradient grows while others starve (co-adaptation loop, \S\ref{sec:rrmoa}).}
\label{fig:trajectory}
\end{figure}
\vspace{-4pt}

\begin{figure}[h]
\centering
\includegraphics[width=0.78\columnwidth]{figures/causal_contrast.pdf}
\vspace{-4pt}
\caption{\textbf{Causal contrast: MOMENT vs Timer-XL} (ETTh1, last-4 unfreezing). MOMENT entropy collapses $0.51{\to}0.000$ in ${\sim}40$ steps (red); Timer-XL stays at ${\approx}1.60$ for all $400$ steps (orange). Same code, same data, only normalization differs. Pattern generalizes across all 3 tested datasets.}
\label{fig:causal_contrast}
\end{figure}

In contrast, \textbf{RR-MoA} maintains healthy routing entropy ($1.0$--$1.57$) and wins \textbf{54/54} configurations, with MSE improvements of $27\%$ to $77\%$ over the best fixed adapter. Notably, on Traffic ($R{=}0.14$, where the stripped statistics carry little information), RR-MoA does not improve over fixed adapters---exactly as Observation~\ref{thm:mi_decomp} predicts (Figure~\ref{fig:signal_ratio}).

\textbf{Rescue-baseline sweep.} To rule out that the collapse is merely under-tuned, we sweep eleven standard MoE rescue mechanisms---Switch load-balance~\citep{fedus2022switch}, ST-MoE z-loss~\citep{zoph2022stmoe}, entropy regularization, ReMoE ReLU routing~\citep{zhang2025remoe}, and expert-choice routing~\citep{zhou2022expertchoice}---across 6 datasets $\times$ 2 freeze levels $\times$ 5 seeds $= 720$ runs (Table~\ref{tab:rescue}, Appendix~\ref{app:rescue_details}). The best rescue (z-loss $c_z{=}0.01$) reduces MSE by only $10.9\%$, still $2.7{\times}$ worse than RR-MoA. Excessive balancing ($\alpha{=}10.0$) is catastrophic ($+67.7\%$). This confirms Observation~\ref{thm:mi_decomp}(ii): when routing information is structurally absent from the hidden states, no optimization-side trick can compensate.

\textbf{Self-routing and architecture-agnostic validation.} To confirm the bottleneck is in the routing \emph{input} rather than the router \emph{architecture}, we test two additional controls. First, Self-Routed MoA (SR-MoA)~\citep{lv2025aoe,cheng2025ermoe,liu2026routingfree}: each expert contains its own sigmoid gate---no external router. On raw input, SR-MoA \emph{outperforms} RR-MoA by $13$--$42\%$ across all 6 datasets (ETTh1: $0.464$; ETTm1: $0.388$; Weather: $0.222$; 252 runs total), generalizes across six backbones, and independently replicates the Frozen Paradox (frozen best on 4/6 datasets; Table~\ref{tab:self_routed}). The same architecture gating on hidden states degrades by $+87\%$ to $+768\%$ on \textbf{all 6 datasets} ($p{=}0.016$, Wilcoxon). \textbf{Normalization-specificity:} on Timer-XL (no RevIN), the same raw-vs-hidden comparison yields only $+4$--$9\%$---$15$--$100{\times}$ smaller than on MOMENT---confirming the degradation is normalization-induced. Second, replacing AdaMix's hidden-state router with a raw-input router recovers entropy to $1.41$--$1.57$ and MSE by $41$--$88\%$ on all 12 cells (Appendix~\ref{app:adamix_details}). Both confirm the diagnosis: the bottleneck is normalization, not router design. \textbf{Summary of converging controls:} (C1)~RevIN ablation recovers entropy (Table~\ref{tab:adamix}, green rows); (C2)~opposite trajectories on MOMENT vs Timer-XL (Figure~\ref{fig:causal_contrast}); (C3)~BatchNorm1d and GroupNorm collapse identically (Appendix~\ref{app:norm_generalization}); (C4)~11 rescue mechanisms fail (Table~\ref{tab:rescue}); (C5)~raw-input AdaMix router recovers (Appendix~\ref{app:adamix_details}); (C6)~SR-MoA raw vs hidden ($+87$--$768\%$; Table~\ref{tab:self_routed}); (C7)~cross-modality replication on ViT (Appendix~\ref{app:vision_moe}); (C8)~re-injecting $(\mu,\sigma)$ into hidden states does \emph{not} recover routing ($+42$--$239\%$; Appendix~\ref{app:reinjection}).

{\looseness=-1 \textbf{Why the simplicity of the fix is the point.} The contribution is the \emph{diagnosis}, not the fix. Before this work, MoE routing collapse was treated as an optimization problem (load balancing, entropy regularization, z-loss) and the assumption was that better training recipes would resolve it. We show it is an \emph{information} problem: normalization structurally removes the signal the router needs, and no optimization-side trick can compensate (eleven mechanisms, 720 runs; Table~\ref{tab:rescue}). That the fix is unambiguous---route on the signal that was stripped---is evidence that the causal mechanism is correctly identified.}
\vspace{-0.3em}

\begin{table}[h]
\centering
\caption{\textbf{Baseline comparison} (MOMENT-small, Top-2, 5 seeds, H=96). Above double rule: frozen; full FT unfreezes all 8 blocks. Wilcoxon, Bonferroni-corrected. Grey rows: from-scratch calibration anchors.}
\label{tab:baselines}
\small
\begin{tabular}{@{}lcccc@{}}
\toprule
Method & ETTh1 & ETTm1 & Weather & $p$-value \\
\midrule
Best fixed adapter & $1.254 \pm 0.026$ & $1.148 \pm 0.035$ & $0.528 \pm 0.018$ & ${<}0.001^{***}$ \\
Best LoRA (108-run sweep) & $1.154 \pm 0.000$ & $0.956 \pm 0.072$ & $0.600 \pm 0.052$ & ${<}0.001^{***}$ \\
TRACE (frozen) & $1.195 \pm 0.026$ & $1.014 \pm 0.073$ & $0.457 \pm 0.015$ & ${<}0.001^{***}$ \\
Ind.\ Ensemble (5 experts) & $1.081 \pm 0.021$ & $1.049 \pm 0.032$ & $0.509 \pm 0.024$ & ${<}0.001^{***}$ \\
