\section{Proposition Proofs}
\label{app:proofs}

\begin{figure}[h]
\centering
\resizebox{0.85\columnwidth}{!}{%
\input{figures/tikz_decomposition.tex}%
}
\caption{\textbf{Signal decomposition and routing information loss.} A raw window $\mathbf{X}$ decomposes into mean $\mu$, scale $\sigma$, and shape $S$. RevIN discards $(\mu, \sigma)$, destroying routing information (Observation~\ref{thm:mi_decomp}). The raw router preserves all three components, enabling diverse per-sample routing.}
\label{fig:decomposition}
\end{figure}

\textbf{Proof of Observation~\ref{thm:mi_decomp}} (Routing Information Loss Under RevIN, revised form).

\begin{proof}
Throughout, $X$ denotes a raw window, $(M,\Sigma)$ its per-window mean/scale, $S = (X-M)/\Sigma$ its RevIN-normalized shape, and $E$ a deterministic (possibly randomized) router assignment. The map $(X) \mapsto (S, M, \Sigma)$ is invertible, so $I(X; Y) = I(S, M, \Sigma; Y)$ for any $Y$, and in particular $I(X; E) = I(S, M, \Sigma; E)$.

\emph{Part (i): Exact decomposition.} By the chain rule of mutual information applied to $(S, M, \Sigma; E)$,
\begin{align*}
I(X; E) \;=\; I(S, M, \Sigma;\, E) \;=\; I(S;\, E) + I(M, \Sigma;\, E \mid S).
\end{align*}
Rearranging, $I(X; E) - I(S; E) = I(M, \Sigma;\, E \mid S) \geq 0$. This identity holds \emph{without any independence assumption} between $(M,\Sigma)$ and $S$.

\emph{Part (ii): Unconditional quantitative bound.} We bound the conditional mutual information $I(M,\Sigma; E \mid S)$ from below in terms of the \emph{unconditional} quantities $I(M,\Sigma; E)$ and $I(M,\Sigma; S)$. Applying the chain rule two different ways to $I(M,\Sigma; E, S)$,
\begin{align*}
I(M,\Sigma;\, E, S) &= I(M,\Sigma;\, S) + I(M,\Sigma;\, E \mid S) \qquad\text{(expand $S$ first)} \\
                    &= I(M,\Sigma;\, E) + I(M,\Sigma;\, S \mid E) \qquad\text{(expand $E$ first).}
\end{align*}
Equating and solving for $I(M,\Sigma; E \mid S)$,
\[
I(M,\Sigma;\, E \mid S) \;=\; I(M,\Sigma;\, E) \;-\; I(M,\Sigma;\, S) \;+\; I(M,\Sigma;\, S \mid E).
\]
Since $I(M,\Sigma; S \mid E) \geq 0$ (mutual information is non-negative), we obtain
\[
I(X; E) - I(S; E) \;=\; I(M,\Sigma;\, E \mid S) \;\geq\; I(M,\Sigma;\, E) \;-\; I(M,\Sigma;\, S),
\]
where the residual $\varepsilon := I(M,\Sigma; S) \geq 0$ is the \emph{leakage} of location-scale statistics into the shape. Equality (tightness) holds iff $I(M,\Sigma; S \mid E) = 0$, i.e.\ iff $(M,\Sigma)$ and $S$ are conditionally independent given $E$. In particular, unconditional independence $(M,\Sigma) \perp\!\!\!\perp S$ implies $\varepsilon = 0$ and recovers the classical $I(X;E) - I(S;E) \geq I(M,\Sigma; E)$ bound as a corollary.

\emph{Part (iii): Full-information corner.} Suppose the router depends entirely on the stripped statistics: $E \perp\!\!\!\perp S \mid (M, \Sigma)$, which means $p(E \mid S, M, \Sigma) = p(E \mid M, \Sigma)$. Then the Markov chain $S \to (M,\Sigma) \to E$ holds, and by the DPI $I(S; E) \leq I(M,\Sigma; E)$ but also $I(S; E) = 0$ whenever the Markov chain's first step $S \to (M,\Sigma)$ conveys no information (which holds when $(M,\Sigma) \perp\!\!\!\perp S$). In the full-information corner case $(M,\Sigma) \perp\!\!\!\perp S$ and $E$ determined by $(M,\Sigma)$, we have $I(S;E) = 0$ and $I(X;E) = I(M,\Sigma;E) = H(E) - H(E \mid M,\Sigma) = H(E)$. Hence $I(X;E) - I(S;E) = H(E)$: RevIN destroys the entire routing distribution.

\emph{Part (iv): Empirical leakage and signal ratio.} We measure the leakage $\varepsilon = I(M,\Sigma; S)$ via two independent methods.

\emph{Gaussian reference.} Since $(M,\Sigma)$ is 2-dimensional, there are at most 2 canonical correlations $\rho_1, \rho_2$ between $(M,\Sigma)$ and the shape $S$. For jointly Gaussian variables, $I(M,\Sigma; S) = -\frac{1}{2}\sum_{i=1}^2 \log(1 - \rho_i^2)$. This yields $\varepsilon_\text{Gauss}$ ranging from $0.09$ nats (Weather, $\rho_\text{max}{=}0.35$) to $1.26$ nats (Exchange, $\rho_\text{max}{=}0.89$). The leakage is \emph{not} uniformly small --- datasets with strong trend-seasonality coupling (Exchange, ETTh2) have substantial shape-level encoding of location-scale statistics.

\emph{Distribution-free cross-check.} Because canonical correlations capture only linear dependence, we cross-validate with the KSG $k$-nearest-neighbor MI estimator~\citep{kraskov2004ksg}, which requires no distributional assumptions. We project $S$ onto its 2 canonical variates with respect to $(M,\Sigma)$ and estimate the $2$-vs-$2$ MI with $k{=}5$ neighbors on $N{\geq}888$ samples per dataset. The KSG estimates agree with the Gaussian reference within $\pm 0.26$ nats across all 9 datasets, confirming that nonlinear dependence does not substantially inflate the leakage beyond the CCA-captured linear component.

\emph{Tightness condition.} The bound~(ii) is informative when $I(M,\Sigma; E) \gg \varepsilon$. Since $I(M,\Sigma; E)$ increases with the location-scale variance, the signal ratio $R(\mathcal{D}) = [\mathrm{Var}(M) + \mathrm{Var}(\Sigma)] / \overline{\mathrm{Var}(S)}$ is a monotone proxy for the tightness of the bound. This explains the $\rho{=}{-}0.88$ correlation: high-$R$ datasets (Exchange, $R{=}2.17$) have $I(M,\Sigma; E) \gg \varepsilon$, producing large gains ($-68.5\%$); low-$R$ datasets (Traffic, $R{=}0.14$) have $I(M,\Sigma; E) \approx \varepsilon$, producing no gain ($+2.9\%$).
\end{proof}

\textbf{Remark on the classical form.} The earlier version assumed $(M,\Sigma) \perp\!\!\!\perp S$ outright. The revised form~(ii) keeps $\varepsilon$ explicit and Part~(iv) measures it via both parametric (CCA) and non-parametric (KSG) methods, eliminating the independence assumption. Part~(v) bypasses the bound entirely by directly measuring $H(E \mid S)$, confirming the gap $I(M,\Sigma; S \mid E)$ averages $0.075$ nats (Table~\ref{tab:mi_tightness}). The agreement between Gaussian reference and distribution-free KSG estimates ($\pm 0.26$ nats) confirms the CCA-based values are reliable despite non-Gaussianity.

\subsection{Theoretical Depth of Observation~\ref{thm:mi_decomp}}
\label{app:prop2_depth}

While the MI decomposition in Observation~\ref{thm:mi_decomp} is algebraically a chain-rule identity, it has deeper information-theoretic content when connected to rate-distortion theory and phase transitions.

\textbf{Rate-distortion interpretation of $R(\mathcal{D})$.}
Instance normalization is a \emph{deterministic lossy compression}: it maps $X \mapsto S$, discarding $(M, \Sigma)$. In rate-distortion theory~\citep{cover2006elements}, this compression has rate $R_\text{strip} = I(X; M, \Sigma \mid S)$ and distortion (for routing) $D_\text{route} = H(E \mid S) - H(E \mid X) = I(M, \Sigma; E \mid S)$, which is exactly Observation~\ref{thm:mi_decomp}(i). Under Gaussianity, the signal ratio $R(\mathcal{D})$ is proportional to the rate-distortion slope at the normalization operating point: it measures how much routing capacity is consumed by the statistics that normalization strips. Specifically, if the joint $(M, \Sigma, S)$ is multivariate Gaussian, then $I(M, \Sigma; E) \propto \log(1 + R(\mathcal{D}))$ (by the Gaussian mutual information formula), making $R(\mathcal{D})$ a \emph{monotone surrogate for the bits lost to normalization}. The validated $\rho = -0.88$ correlation (Figure~\ref{fig:signal_ratio}) is thus not a statistical coincidence but a consequence of this rate-distortion structure.

\begin{proposition}[Phase Transition in Routing Quality]
\label{prop:phase_transition}
Consider a softmax router on the interpolated input $\mathbf{x}_\alpha = (1{-}\alpha)\,\mathbf{x}_\mathrm{raw} + \alpha\,\mathrm{RevIN}(\mathbf{x}_\mathrm{raw})$. Under the Gaussian model with approximately orthogonal $(M,\Sigma)$ and $S$ (leakage $\varepsilon$ small), the effective routing signal power is:
\[
    P_\mathrm{route}(\alpha) \;=\; (1{-}\alpha)^2 \cdot [\mathrm{Var}(M) + \mathrm{Var}(\Sigma)] \;+\; \alpha^2 \cdot \overline{\mathrm{Var}(S)} \;+\; 2\alpha(1{-}\alpha)\,\mathrm{Cov}_\mathrm{cross}
\]
Routing discriminability crosses the router's noise floor at a critical normalization threshold:
\[
    \alpha^* \;\approx\; \frac{R(\mathcal{D})}{R(\mathcal{D}) + 1}

\]
For $\alpha < \alpha^*$, routing quality degrades continuously; for $\alpha \to 1$, routing collapses discontinuously due to the softmax's exponential sensitivity to signal-to-noise ratio.
\end{proposition}

\emph{Validation.} For the median $R(\mathcal{D}) = 0.67$ across our benchmarks, Proposition~\ref{prop:phase_transition} predicts $\alpha^* \approx 0.40$. The dose-response experiment (Figure~\ref{fig:dose_response}; 150 runs) confirms this: MSE degrades mildly for $\alpha \leq 0.75$ ($+5.4\%$) but catastrophically at $\alpha = 1.0$ ($+283\%$). The sharpness of the transition arises from the softmax: when $P_\mathrm{route}(\alpha) / P_\mathrm{noise}$ drops below ${\sim}1$, routing weights converge to uniform regardless of expert relevance.

\textbf{Information bottleneck connection.}
The RevIN-encoder pipeline implements a form of the information bottleneck~\citep{tishby2000ib}: it compresses $X$ into a representation $H = f_\theta(S)$ that is optimized for downstream prediction while discarding ``irrelevant'' variability (the per-window location-scale statistics). The routing MI loss from Observation~\ref{thm:mi_decomp}(i) is the price paid for this compression \emph{at the routing decision point}. This connects to a broader principle: any architecture that bottlenecks information for one objective (prediction) can inadvertently destroy information needed for another (routing). The vision cross-modality control (Appendix~\ref{app:vision_moe}) confirms this is not RevIN-specific: InstanceNorm1d on ViT patches creates the same bottleneck, while InstanceNorm2d on ResNet spatial features does not---because spatial features are not the routing signal for classification.

\textbf{Proof of Proposition~\ref{prop:hierarchy}} (Strict Head-Level Hierarchy: $\mathcal{C}_\text{head} \subset \mathcal{G}_\text{tmpl} \subset \mathcal{G}_\text{code}$).

\begin{proof}
\emph{$\mathcal{C}_\text{head} \subseteq \mathcal{G}_\text{tmpl}$}: Each $c \in \mathcal{C}_\text{head}$ is, by Definition~\ref{def:discrete_head}, a pooling strategy followed by an MLP head. Both components are expressible as template derivations of the form $S \to \text{Pool}\cdot\text{MLP}\cdot\text{Output}$ (Appendix~\ref{app:grammar}), so $c$ lies in $\mathcal{G}_\text{tmpl}$. \emph{Strict}: $\mathcal{G}_\text{tmpl}$ additionally admits Conv1d pooling and SiLU activations absent from $\mathcal{C}_\text{head}$.

\emph{$\mathcal{G}_\text{tmpl} \subseteq \mathcal{G}_\text{code}$}: Every template derivation produces a valid Python program satisfying Definition~\ref{def:code}. \emph{Strict}: $\mathcal{G}_\text{code}$ contains depthwise convolutions, batch normalization, residual connections, and learned positional weights---none derivable from the template grammar (Table~\ref{tab:expressiveness}).

\emph{Orthogonality of LoRA and bottleneck configurations.} Configurations in $\mathcal{C}\setminus\mathcal{C}_\text{head}$ modify the backbone's attention projections (LoRA) or inject residual modules between encoder blocks (bottleneck). They are not head-level adapters and are therefore not members of $\mathcal{G}_\text{tmpl}$ nor of $\mathcal{G}_\text{code}$ as defined (the code space is restricted to adapter classes operating on extracted hidden states, per Definition~\ref{def:code}). We compare against the LoRA variant separately under the strictly frozen backbone protocol in Table~\ref{tab:baselines}.
\end{proof}

\textbf{Proof of Proposition~\ref{prop:frozen}} (Gradient Co-Adaptation Drives Entropy Collapse).

\begin{proof}
Consider a single input $\mathbf{x}$ with backbone $\mathbf{h} = A\mathbf{x}$, router $p = \sigma(\mathbf{w}^\top\mathbf{h})$, and loss $\ell = p\,\ell_1(\mathbf{h}) + (1-p)\,\ell_2(\mathbf{h})$.

\emph{Part (i): Unfrozen backbone.} The gradient with respect to $A$ is:
\begin{equation*}
\frac{\partial\ell}{\partial A} = p\,\frac{\partial\ell_1}{\partial\mathbf{h}}\mathbf{x}^\top + (1{-}p)\,\frac{\partial\ell_2}{\partial\mathbf{h}}\mathbf{x}^\top + (\ell_1 - \ell_2)\,p(1{-}p)\,\mathbf{w}\mathbf{x}^\top
\end{equation*}
Under gradient descent $\dot{A} = -\eta\,\partial\ell/\partial A$, the induced change in expert~1's loss is:
\begin{multline*}
\dot{\ell}_1\big|_A = -\eta\|\mathbf{x}\|^2\!\Bigg[p\left\|\frac{\partial\ell_1}{\partial\mathbf{h}}\right\|^2 + (1{-}p)\left(\frac{\partial\ell_1}{\partial\mathbf{h}}\right)^{\!\top}\frac{\partial\ell_2}{\partial\mathbf{h}} \\
 + (\ell_1{-}\ell_2)\,p(1{-}p)\left(\frac{\partial\ell_1}{\partial\mathbf{h}}\right)^{\!\top}\mathbf{w}\Bigg]
\end{multline*}
The first term (self-gradient) always decreases $\ell_1$. The second (cross-gradient) is negligible when expert gradients are approximately orthogonal---a condition that holds empirically once experts specialize to distinct input clusters (Appendix~\ref{app:routing_weights}). The third (loss-coupling) term is small early in training when $|\ell_1 - \ell_2| \ll \|\partial\ell_1/\partial\mathbf{h}\|$. Retaining only the dominant first term:
\begin{equation*}
\dot{\ell}_1\big|_A \approx -\eta\,p\left\|\frac{\partial\ell_1}{\partial\mathbf{h}}\right\|^2\|\mathbf{x}\|^2
\end{equation*}
and analogously $\dot{\ell}_2\big|_A \approx -\eta\,(1{-}p)\left\|\frac{\partial\ell_2}{\partial\mathbf{h}}\right\|^2\|\mathbf{x}\|^2$. When $p > 1{-}p$ (expert~1 dominates), $\ell_1$ decreases faster than $\ell_2$. The third term in $\partial\ell/\partial A$ further reinforces this: when $\ell_1 < \ell_2$, the factor $(\ell_1 - \ell_2) < 0$ drives $\dot{p} > 0$, pushing $p$ toward~1. Together these create the self-reinforcing loop: dominant expert gets more gradient $\to$ its loss drops faster $\to$ router increases its weight $\to$ it becomes more dominant.

\emph{Part (ii): Frozen backbone.} When $A$ is fixed, $\dot{A} = 0$. The only dynamics are through $\mathbf{w}$:
\begin{equation*}
\dot{\mathbf{w}} = -\eta\,\frac{\partial\ell}{\partial\mathbf{w}} = -\eta\,(\ell_1 - \ell_2)\,p(1{-}p)\,\mathbf{h}
\end{equation*}
This update adjusts routing weights based on current expert performance, but does \emph{not} reshape $\mathbf{h}$ to favor one expert. Without the $A$-mediated feedback loop, there is no systematic bias toward entropy collapse---the router converges to a stable allocation reflecting the static geometry of the fixed representation space.
\end{proof}

\textbf{Budget Sufficiency (Empirical).} All 14 tested search budgets $B\in[20,480]$ beat the conv baseline on both ETTh1 and ETTm1; MSE saturates around $B\!\approx\!60$ (Appendix~\ref{app:budget}). Evolutionary selection did not outperform random sampling in $\mathcal{G}_\text{tmpl}$.

\section{AAS Search Details}
\label{app:aas_details}

The AAS loop maintains a population of 20 adapters over 12 generations (${\sim}240$ evaluations, 3-epoch fitness probes). Elitism preserves the top 2; an LLM variant generates candidates in the code space $\mathcal{G}_\text{code}$. Template-based generation achieves 100\% validity (vs.\ ${\sim}75\%$ for LLM).

\subsubsection*{Template Grammar Production Rules}
\label{app:grammar}

\begin{align*}
S &\rightarrow \nonterminal{Pool} \;\cdot\; \nonterminal{MLP} \;\cdot\; \nonterminal{Output} \\
\nonterminal{Pool} &\rightarrow \text{MeanPool} \mid \text{MaxPool} \mid \text{LastToken} \mid \text{AttnPool} \mid \text{Conv1dPool} \\
\nonterminal{MLP} &\rightarrow \nonterminal{Layer} \mid \nonterminal{Layer} \;\cdot\; \nonterminal{MLP} \quad (\text{depth} \leq 3) \\
\nonterminal{Layer} &\rightarrow \text{Linear}(d_\text{in}, d_\text{out}) \;\cdot\; \nonterminal{Act} \;\cdot\; \text{Dropout}(p) \\
\nonterminal{Act} &\rightarrow \text{GELU} \mid \text{ReLU} \mid \text{SiLU} \mid \text{Tanh} \\
\nonterminal{Output} &\rightarrow \text{Linear}(d_\text{last}, H)
\end{align*}
with $d_\text{out} \in \{64, 128, 192, 256, 384\}$ and $p \in \{0.0, 0.1, 0.2, 0.3\}$, yielding $|\mathcal{G}_\text{tmpl}| \approx 1{,}200$.

